<script setup lang="ts">
import {computed,onBeforeUnmount,reactive,ref,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {useSession} from '../../session'
import {ObjectLease} from '../../object-lease'
import {uuid,decimal} from '../finance/finance-client'
import {balance,canReadMoney,canWriteMoney,cents,moneyTransport,yuan,type MoneyAction} from './money-client'
import {MoneyWork} from './money-work'
import {MoneyVoucher} from './money-voucher'
import MoneyCorrectionReview from './MoneyCorrectionReview.vue'
const auth=useSession(),route=useRoute(),router=useRouter(),input=ref(''),action=ref<MoneyAction>('assess'),bill=ref(''),line=ref(''),completion=ref(''),digest=ref(''),approval=ref(''),original=ref(''),evidence=ref(''),amount=ref(''),reason=ref(''),consent=ref(false),after=ref('0')
let alive=true
const newBill=()=>{bill.value=crypto.randomUUID()}
const coveredLines=ref([{lineId:'',amount:''}])
const ticket=ref(''),business=ref<string>(crypto.randomUUID()),reference=ref(''),date=ref(''),method=ref(''),selected=ref<File|null>(null)
const group=computed(()=>String(route.params.groupId??'')),owner=()=>auth.phase==='NORMAL'&&canReadMoney(auth.identity)?{slot:JSON.stringify([auth.identity!.tenant!.id,auth.identity!.userId,group.value]),stamp:JSON.stringify([auth.identity!.tenant!.id,auth.identity!.userId,auth.generation,auth.identity!.loginAttemptId,group.value])}:null,context=()=>owner()?.stamp??'',send=moneyTransport(auth,()=>alive)
const account=reactive(new ObjectLease(auth,context,async()=>balance(await send('GET',group.value)))),history=reactive(new ObjectLease<{version:string;operationId:string;action:string;summary:unknown}[]>(auth,()=>context()+after.value,async()=>{const v=await send('GET',group.value,'/entries?afterVersion='+after.value+'&limit=20') as {entries:unknown[]};if(!v||!Array.isArray(v.entries)||v.entries.length>20)throw Error('流水无法确认');let previous=BigInt(after.value);for(const row of v.entries){const r=row as {version:string;operationId:string;action:string};if(!decimal(r.version)||BigInt(r.version)<=previous||!uuid(r.operationId)||typeof r.action!=='string')throw Error('流水顺序无法确认');previous=BigInt(r.version)}return v.entries as {version:string;operationId:string;action:string;summary:unknown}[]})),work=reactive(new MoneyWork(send,owner))
function reset(){bill.value='';line.value='';completion.value='';digest.value='';approval.value='';original.value='';evidence.value='';amount.value='';reason.value='';consent.value=false}
const vouchers=reactive(new MoneyVoucher(auth,owner))
async function refresh(){account.clear();history.clear();consent.value=false;if(owner()&&uuid(group.value)){await account.refresh();if(account.value)await history.refresh()}}
watch(context,()=>{work.bind();reset();account.clear();history.clear();after.value='0';void refresh()},{immediate:true,flush:'sync'})
watch(context,()=>{vouchers.bind();ticket.value=vouchers.current?.ticket??'';business.value=vouchers.current?.command.businessId??crypto.randomUUID();selected.value=null;reference.value='';date.value='';method.value=''},{immediate:true,flush:'sync'})
watch(action,()=>{reset();selected.value=null;consent.value=false;business.value=vouchers.current?.command.businessId??crypto.randomUUID()})
function pick(e:Event){selected.value=(e.target as HTMLInputElement).files?.[0]??null;consent.value=false}
function nextVoucher(){if(!work.pending&&!work.busy&&vouchers.current?.fact?.state==='READY'){vouchers.clearReady();business.value=crypto.randomUUID();reference.value='';date.value='';method.value='';amount.value='';selected.value=null;consent.value=false}}
async function prepareVoucher(){if(selected.value)await vouchers.prepare(ticket.value,group.value,business.value,action.value==='refund'?'FINANCE_REFUND':'FINANCE_COLLECTION',selected.value)}
function moneyFields(){const f=vouchers.current?.fact,c=vouchers.current?.command;if(!f||f.state!=='READY'||!c||c.businessId!==business.value||c.groupId!==group.value||c.purpose!==(action.value==='refund'?'FINANCE_REFUND':'FINANCE_COLLECTION')||!reference.value.trim()||reference.value.length>100||!/^\d{4}-\d\d-\d\d$/.test(date.value)||!method.value.trim()||method.value.length>40)throw Error('必须使用当前业务真实READY私有凭证，并填写参考号、日期与方式');const voucher={reference:reference.value,date:date.value,method:method.value,privateFileId:f.fileId,evidenceDigest:f.sha256},n=cents(amount.value);if(n==='0')throw Error('实际收退款及非零重记金额必须大于零');if(action.value==='refund'){if(!uuid(original.value))throw Error('原收款无效');return {refundId:business.value,originalPaymentId:original.value,amountCents:n,voucher}}if(!uuid(bill.value))throw Error('账单无效');if(action.value==='rebook'){if(!uuid(original.value)||!uuid(evidence.value)||!reason.value.trim())throw Error('原收款与调查依据不完整');return {originalPaymentId:original.value,correctionEvidenceId:evidence.value,reason:reason.value,billId:bill.value,paymentId:business.value,amountCents:n,voucher}}return {billId:bill.value,paymentId:business.value,amountCents:n,voucher,correctionOf:null}}
async function submit(){if(!consent.value||!account.value||work.pending||!canWriteMoney(auth.identity,action.value))return;try{const body:Record<string,unknown>={expectedVersion:account.value.version,expectedGroupVersion:groupVersion.value};if(!decimal(groupVersion.value))throw Error('当前费用组版本无效');if(action.value==='assess'){if(!uuid(bill.value)||!uuid(completion.value)||!coveredLines.value.length||coveredLines.value.length>50||coveredLines.value.some(l=>!uuid(l.lineId))||new Set(coveredLines.value.map(l=>l.lineId)).size!==coveredLines.value.length||!/^[0-9a-f]{64}$/.test(digest.value))throw Error('请核验账单、completion、覆盖行与摘要');Object.assign(body,{billId:bill.value,completionId:completion.value,coverageDigest:digest.value,lines:coveredLines.value.map(l=>({lineId:l.lineId,amountCents:cents(l.amount)}))})}else if(action.value==='lower'){if(!uuid(bill.value)||!uuid(line.value)||!uuid(approval.value)||!/^[0-9a-f]{64}$/.test(digest.value)||!reason.value.trim())throw Error('应收调整依据不完整');Object.assign(body,{billId:bill.value,lineId:line.value,newCents:cents(amount.value),adjustmentApprovalId:approval.value,coverageDigest:digest.value,reason:reason.value})}else if(action.value==='reverse'){if(!uuid(original.value)||!uuid(evidence.value)||!reason.value.trim())throw Error('请填写原收款与真实调查依据');Object.assign(body,{originalPaymentId:original.value,correctionEvidenceId:evidence.value,reason:reason.value})}else Object.assign(body,moneyFields());await work.start(group.value,action.value,body);if(work.phase==='SUCCEEDED')await refresh()}catch(e){work.error=e instanceof Error?e.message:'表单无法确认'}consent.value=false}
const groupVersion=ref(''),actions:MoneyAction[]=['assess','lower','collect','reverse','refund','rebook'],labels={assess:'核定应收',lower:'降低应收',collect:'登记实际线下收款',reverse:'零资金错录冲正',refund:'核销实际线下退款',rebook:'非零资金原子冲正重记'}
watch(()=>JSON.stringify([bill.value,line.value,completion.value,digest.value,approval.value,original.value,evidence.value,amount.value,reason.value,groupVersion.value,ticket.value,business.value,reference.value,date.value,method.value,coveredLines.value]),()=>{consent.value=false},{flush:'sync'})
function visibility(){account.clear();history.clear();reset();if(document.visibilityState!=='hidden')void refresh()}
document.addEventListener('visibilitychange',visibility);const timer=setInterval(()=>{account.expire();history.expire()},1000)
onBeforeUnmount(()=>{alive=false;clearInterval(timer);account.dispose();history.dispose();work.dispose();vouchers.dispose();document.removeEventListener('visibilitychange',visibility)})
</script>
<template><section class="page-heading"><h1>线下资金登记</h1><p>人工登记，未接支付渠道。结算未完成本身不阻止维修关闭。所有事实与权限由服务端核验。</p></section><section class="panel"><label>当前授权费用组UUID<input v-model="input"></label><button :disabled="!uuid(input)" @click="router.push('/money/'+input)">查询费用组资金</button><p v-if="!canReadMoney(auth.identity)">当前账号没有资金读取能力。</p><p>费用组 {{group}}</p><button :disabled="!uuid(group)||!canReadMoney(auth.identity)||account.busy" @click="refresh">重新核验当前余额与权限</button><p role="alert">{{account.error||history.error}}</p><dl v-if="account.value"><template v-for="[key,label] in [['receivableCents','应收'],['collectedCents','有效实收'],['refundedCents','已退款'],['settledCents','已结算'],['outstandingCents','未收'],['overpaymentCents','多收待处理']]" :key="key"><dt>{{label}}</dt><dd>{{yuan(String(account.value[key as keyof typeof account.value]))}} 元</dd></template></dl></section>
<section v-if="account.value" class="panel"><h2>资金动作</h2><RouterLink :to="'/money-reviews/'+group">应收调整申请与错录调查</RouterLink><select v-model="action"><option v-for="a in actions" :key="a" :value="a">{{labels[a]}}</option></select><label>当前费用组版本<input v-model="groupVersion" inputmode="numeric"></label><template v-if="action==='assess'||action==='lower'"><label>账单UUID（核定新账单请自行生成）<input v-model="bill"><button @click="newBill">生成新账单UUID</button></label><template v-if="action==='assess'"><fieldset v-for="(covered,i) in coveredLines" :key="i"><label>已授权执行覆盖行UUID<input v-model="covered.lineId"></label><label>本行核定金额（元）<input v-model="covered.amount" inputmode="decimal"></label><button :disabled="coveredLines.length===1" @click="coveredLines.splice(i,1)">移除此行</button></fieldset><button :disabled="coveredLines.length>=50" @click="coveredLines.push({lineId:'',amount:''})">增加核定行</button></template><template v-else><label>批准行UUID<input v-model="line"></label><label>降低后金额（元）<input v-model="amount" inputmode="decimal"></label></template><label>权威覆盖摘要<input v-model="digest"></label><label v-if="action==='assess'">已完成审批completion UUID<input v-model="completion"></label><label v-else>调整审批UUID<input v-model="approval"></label></template><template v-if="action==='reverse'"><label>原收款UUID<input v-model="original"></label><label>实际未退资金为零的调查依据UUID<input v-model="evidence"></label></template><template v-if="['collect','refund','rebook'].includes(action)"><label>工单UUID<input v-model="ticket" :disabled="!!vouchers.current"></label><label>账单UUID<input v-model="bill"></label><label>金额（元）<input v-model="amount" inputmode="decimal"></label><label v-if="action!=='collect'">原收款UUID<input v-model="original"></label><label v-if="action==='rebook'">错录调查依据UUID<input v-model="evidence"></label><p>业务UUID {{business}}。请上传实际线下{{action==='refund'?'已完成退款':'已核实到账'}}凭证；文件可用不等于资金发生。</p><input type="file" accept="application/pdf,image/png,image/jpeg" :disabled="!!vouchers.current" @change="pick"><button :disabled="!selected||vouchers.busy||!!vouchers.current||!uuid(ticket)" @click="prepareVoucher">准备原凭证上传</button><p role="alert">{{vouchers.error}}</p><template v-if="vouchers.current"><p>原上传UUID {{vouchers.current.command.operationId}} · {{vouchers.current.phase}}</p><button :disabled="vouchers.busy" @click="vouchers.perform('query')">查询原上传</button><button v-if="['PREPARED','NOT_OBSERVED'].includes(vouchers.current.phase)" :disabled="vouchers.busy" @click="vouchers.perform('register')">显式原键登记文件</button><button v-if="vouchers.current.fact?.state==='UPLOADING'" :disabled="vouchers.busy" @click="vouchers.perform('upload')">显式上传原文件内容</button><a v-if="vouchers.current.fact?.state==='READY'" :href="'/api/ticket/tickets/'+vouchers.current.ticket+'/finance-vouchers/'+vouchers.current.command.operationId+'/content'">鉴权下载已上传凭证</a></template><button :disabled="work.busy||!!work.pending||vouchers.current?.fact?.state!=='READY'" @click="nextVoucher">明确准备下一笔资金及新凭证</button><label>银行/线下参考号<input v-model="reference" maxlength="100"></label><label>实际日期<input v-model="date" type="date"></label><label>实际收退款方式<input v-model="method" maxlength="40"></label></template><label v-if="action!=='assess'">原因<textarea v-model="reason"/></label><label><input type="checkbox" v-model="consent">我已核对原始事实、金额和当前版本，确认提交此动作（真实到账未退不得普通冲正）。</label><button :disabled="!consent||work.busy||!!work.pending||!canWriteMoney(auth.identity,action)" @click="submit">确认{{labels[action]}}</button></section>
<section class="panel"><h2>不可变资金流水</h2><article v-for="e in history.value" :key="e.operationId"><p>版本{{e.version}} · {{e.action}} · 原操作{{e.operationId}}</p><pre>{{e.summary}}</pre></article><button v-if="history.value?.length===20" @click="after=history.value[19]!.version;history.clear();history.refresh()">下一页</button><h2>原UUID恢复</h2><p role="status">{{work.error}}</p><p v-if="work.result">原操作已确认成功：{{work.result.operationId}}，本回执不代表当前余额。</p><template v-if="work.pending"><p>原动作 {{work.pending.action}} · UUID {{work.pending.key}}</p><button :disabled="work.busy" @click="work.query">仅查询原操作</button><button v-if="work.phase==='NOT_OBSERVED'" :disabled="work.busy||!account.value" @click="work.retry">明确以原UUID原参数继续</button></template></section><MoneyCorrectionReview :group="group" /></template>
<style scoped>label{display:block;margin:12px 0}input:not([type=checkbox]),textarea{width:440px;max-width:100%;padding:8px}button{padding:8px;margin:8px}pre,p{white-space:pre-wrap;overflow-wrap:anywhere}dt{float:left;min-width:130px}dd{margin:8px}</style>
